DE_REST_B2 = {
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_0'): 'Ah, was für eine Anstrengung! Meine Muskeln schreien!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_1'): 'Hör zu, du... Ich und der Samurai hier\nhaben die ganze Zeit gerudert!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_10'): 'Hmmm. Ich glaube, diese Höhle führt\nweiter ins Herz der Insel und wird dort\ndann zu einem Gebirgspass.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_11'): 'Auf seinem Gipfel steht das Haus, in dem\ndeine Mutter lebte. Lass uns zuerst dorthin.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_12'): "Huh. Okay, verstanden. Alles klar!\nAuf geht's, Kinder der Menschen!",
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_13'): 'Yaaah!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_14'): 'Äh, nicht du... du bist etwas zu jung.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_15'): 'Kaimaru ist bei mir.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_16'): 'Was ist mit dem Rest von euch?\nWarum bewegt sich niemand?!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_17'): 'Weil... die Insel voller Dämonen ist, was?\nStimmt das, Kinta?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_18'): 'Yui hat recht. Sollen Götter nicht\nuns Menschen schützen?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_19'): 'Grrr... Du frecher kleiner Bengel...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_2'): 'Ich habe das Gefühl, dass meine Arme abfallen.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_20'): 'Du wirst Tauemon genannt, richtig?\nIst dieses Schwert an deiner Hüfte\nnur ein Schmuck?!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_21'): 'Haha... Mein demütigster Dank. Diese Klinge\nmag alten und edlen Ursprungs sein, doch ich\nselbst habe keinerlei Fechten gelernt.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_22'): 'Einst zog ich sie unter\nlebensgefährlichen Umständen,\nda glitt mir der Griff aus den Händen.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_23'): 'Prinzessin...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_24'): 'Alles klar, gut!\nIch gehe allein!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_25'): 'Dann folgen wir deiner Führung.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_3'): 'Na, na. Alles gut.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_4'): 'Nun, Lady Sakuna,\nwas sollen wir jetzt tun?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_5'): 'Gute Frage. Ich werde den Alten befragen.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_6'): 'Alter. Hey, Tama! Schläfst du?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_7'): '*gähn* Also sind wir endlich angekommen.\nDas ist zweifellos die Insel der Dämonen.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_8'): 'Du bist wirklich ein alter Ochsen.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:01000101_9'): 'Du hast offensichtlich zugehört, also erklär\nschnell unser nächstes Ziel.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_0'): 'Mmph... Argh...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_1'): 'Genug! Ich entbinde mich hiermit von\ndieser Pflicht. Recht oder unrecht, ich gehe nach Hause\nund lege mich in mein schönes, warmes Bett.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_10'): 'Prinzessin!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_11'): 'Sie kamen wegen mir?\nIn diesem schrecklichen Schneesturm?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_12'): '*seufz* Ich schätze, ich muss\nzurückkehren und mich um sie kümmern...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_2'): 'Diese Menschen sind mir egal.\nExistieren sie nur, um gegen mich zu schwören\nund mir das Leben schwerer zu machen?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_3'): 'Und Tama auch... Wie wagt er es, sich auf ihre\nSeite zu stellen, wenn er mein Diener sein soll?\nUgh! Alles Heuchler, alle miteinander!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_4'): 'Ich bin fertig, fertig, fertig, fertig, fertiiig!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_5'): 'I-Ich dachte, ich würde sterben...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_6'): 'Das Nachmeer ist wie ein pechschwarzer Abgrund!\nKeine Möglichkeit, mich zu orientieren, keine\nMöglichkeit, den Elementen zu entkommen, nichts zu sehen...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_7'): 'Wie soll ich unter solch grausamen Bedingungen\ndie Hauptstadt erreichen?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_8'): '*schnüff* Waaah!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:02000202_9'): 'Lady Sakuna!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_0'): 'Und da bin ich schon wieder.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_1'): 'Warum bin ich damals hierhergegangen?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_10'): 'Diesmal gibt es keinen Schneesturm. Wenn ich hinaus\nzum Meer rude, selbst wenn ich die Hauptstadt nicht\nerreiche, komme ich vielleicht auf einer anderen Insel an?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_11'): 'Oder lande ich einfach wieder hier?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_12'): 'Ohne mich könnten sie auf dieser Insel\nnicht überleben.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_13'): 'Wenn wir in die Hauptstadt zurückkehrten, fänden\nwenigstens Tama und ich Asyl, und doch...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_14'): 'Ich kann mir nicht vorstellen, dass Lady Kamuhitsuki und die\nanderen Götter sich der Menschen annehmen würden,\ngleich Omizuchis unmittelbarem Angriff...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_15'): 'Und Ashigumo und die Kappa dürften nicht einmal\ndurch die Tore der\nHauptstadt passieren.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_16'): 'Ich habe mich an alle hier gewöhnt.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_17'): 'Ich genieße mein Leben auf dieser Insel.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_18'): 'Plötzlich ist es so offensichtlich.\nDer Einzige mit der Kraft,\ndiesen Ort zu schützen...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_19'): 'Nein, die Kraft zu haben, ist nur die halbe Miete.\nDerjenige, der diesen Ort SCHÜTZEN WILL...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_2'): 'Ich habe das ganze Jahr gearbeitet, wie mir gesagt wurde!\nTag für Tag jagte ich, pflegte die Felder\nund hielt ein waches Auge auf euch alle...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_20'): '...ist niemand anderes als ich, Prinzessin Sakuna!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_21'): 'Ich werde all das bewahren, was ich gewonnen habe!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_22'): 'Hm?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_23'): 'Aaaaah!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_24'): 'Oh, meine Güte. Ich bitte um Entschuldigung.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_25'): 'Ich kam wie versprochen, um nach dir zu sehen.\nÜbrigens, war das eben ein Boot, worauf ich\ngerade gestoßen bin?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_26'): 'Ah, mach dir deshalb keine Sorgen...\n*hust* Erlaube mir, dir den Weg zu zeigen.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_3'): 'Und als Lohn für meine schmerzende Arbeit\nbietet man mir ungenießbaren Abfall an?!\nIst die Welt verrückt geworden?!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_4'): 'Nichts hat sich auch nur im Geringsten verbessert!',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_5'): 'Nichts hat sich... verbessert, was...?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_6'): 'Diese Worte stimmen nun sicherlich.\nIch bin aus ähnlichem Grund wieder geflohen.',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_7'): 'Ich dachte, ich hätte mich verändert.\nWas tue ich denn eigentlich?',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_8'): 'Damals kamen Tama und Tauemon wegen mir,\naber...',
    ('Text/Event/Do/Main_Cove.csvtxt', 'English#c:05000703_9'): 'Diesmal sind sie mit ihren eigenen\nAngelegenheiten beschäftigt.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_0'): 'Es war also er.\nSchlafert er?',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_1'): 'Eine Aura intensiver Bosheit umgibt ihn...\nMeine Haare stehen mir zu Berge!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_10'): 'Heh... Musste ihnen zeigen, wer hier der Boss ist.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_11'): 'Hmph. Wie auch immer, deine Zeit ist abgelaufen.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_12'): 'Ich habe deine Untergebenen besiegt. Du bist\nder Letzte. Gib dich auf und tritt zurück.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_13'): 'Der Letzte, sagst du?',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_14'): 'Diese Dämonen waren nur Show.\nDu hast nichts besiegt, und du wirst es auch nie.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_15'): 'Ich fordere dich auf, es zu versuchen, mich anzufassen!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_16'): 'Es ist Zeit, dir für das zu bezahlen, was du mir an\ndieser Brücke angetan hast. Dann kümmere ich mich um\nKatsura, samt der Frau und den Kindern!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_17'): 'Er kommt, Prinzessin!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_18'): 'Tauemon... Ich werde ihn an deiner Stelle aufhalten!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_2'): 'Es bleibt kein Zweifel, dass er der\nAnführer der Dämonen ist!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_3'): 'Ahh... Ich habe mich gefragt, wer sich hier\neingeschlichen hat. Wenn nicht der Bengel von der Brücke.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_4'): 'In der Tat einige Zeit her. Du bist\nseitdem ziemlich mächtig geworden.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_5'): 'Nun, weißt du. Ich war weit vor euch hier.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_6'): 'Ich hatte reichlich Zeit, meine Klingen zu schleifen,\nwenn du verstehst, was ich meine.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_7'): 'Wenn du wusstest, dass wir kamen, warum hast du\nnicht deine volle Macht gegen uns eingesetzt?',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_8'): 'Ich hatte mit anderem zu tun.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000401_9'): 'Ein paar raue Kerle brauchten eine Tracht Prügel.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_0'): 'Gah... Gaaah!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_1'): 'Habe ich es geschafft?!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_10'): 'Hm? „Schon bald" was, bitte?',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_11'): 'W-Was ist das?! Ein Erdbeben?!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_12'): 'Gah...',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_13'): 'P-Prinzessin, schau!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_14'): 'Der Berg... Er... brennt!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_15'): 'Haaahahaha!\nEs hat begonnen!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_16'): 'Was soll das bedeuten?! Sag es mir!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_17'): 'Sicherlich kennst du seinen Namen schon.\nDer böse Gott Omizuchi ist erwacht!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_18'): 'O-Omizuchi, sagst du?!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_19'): 'Unsinn! Er war...!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_2'): 'Ich bezweifle, dass du dich wie zuvor\nverwandeln kannst.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_20'): 'In der Tat, er wurde von den Göttern in der\nHauptstadt und dem Ashigumo-Stamm niedergestreckt.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_21'): 'Aber er starb nicht! Er entkam und verbarg sich tief in\ndieser Insel und wartete auf seine Zeit.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_22'): 'Was?!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_23'): 'Sobald ich auf dieser Insel ankam,\nfanden wir zueinander.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_24'): 'Er und ich sind ein und dasselbe...\nIch konnte es an ihm riechen -- denselben Gestank von\nunstillbarem Hass und Zorn, den ich so gut kenne.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_25'): 'Ich half, seine Wunden zu heilen, und im\ntausch gab er mir die Macht der Dämonen.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_26'): 'Nachdem wir gemeinsam die Hauptstadt zerstört hatten,\nplanten wir, jene Brücke zu überqueren und das\nNiedrige Reich anzugreifen, aber...',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_27'): 'Schau, was er allein durch sein Erwachen vermag!\nDein Verstand wird sich weigern, wenn er aus\nder Erde hervorbricht.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_28'): 'Er hat solch unglaubliche Macht nur gesammelt,\num die Hauptstadt der Götter in die Luft zu jagen!\nDiese Insel zu zerstören ist für ihn nichts!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_29'): 'Haaahahaha!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_3'): 'Ich lasse dich gehen, also mach dich davon.\nIch habe versprochen, dir das Leben zu schenken.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_30'): 'Urrrgh... Du elender...!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_31'): 'Warte, bitte! Ihn zu töten ändert nichts!\nDu hast Tauemon gegenüber etwas versprochen!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_32'): 'Aber...! Aber...!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_33'): 'Er wird seine gerechte Strafe erhalten, mit der Zeit.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_34'): 'Du weißt ganz genau, wie es einem Menschen ohne\ndämonische Macht auf dieser Insel ergeht.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_35'): 'Stimmt... Wenn er sich nicht auf uns verlässt,\nwird er keinen Frieden finden.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_36'): 'Trotzdem verspricht nichts davon Gutes...',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_4'): 'Du wirst... mich nicht töten?',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_5'): 'Tch. Das ist Katsuras Einmischung, oder?\nDieser lästige kleine...',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_6'): 'Er macht sich Sorgen um dich!',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_7'): 'Du hast vielleicht jetzt keine Worte für ihn,\naber irgendwann solltest du offen mit ihm sprechen.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_8'): 'Wie naiv. Gegebenenfalls würde ich ihm eher\ndie Kehle aufschneiden, als seinem Geschwätz zu lauschen.',
    ('Text/Event/Kin/Main_1_Boss.csvtxt', 'English#c:05000500_9'): 'Übrigens, schon bald...',
}

